const TypewriterText = ({ text, delay = 0, className = "" }: { text: string, delay?: number, className?: string }) => {
  const [displayedText, setDisplayedText] = useState("");
  const [showCursor, setShowCursor] = useState(false);

  useEffect(() => {
    setDisplayedText(""); 
    setShowCursor(false);
    const startTimeout = setTimeout(() => {
      setShowCursor(true);
      let index = 0;
      const intervalId = setInterval(() => {
        setDisplayedText(text.slice(0, index + 1));
        index++;
        if (index >= text.length) clearInterval(intervalId);
      }, 80);
      return () => clearInterval(intervalId);
    }, delay);
    return () => clearTimeout(startTimeout);
  }, [text, delay]);

  return (
    <span className={className}>
      {displayedText}
      {showCursor && <span className="animate-pulse ml-1 inline-block w-1 h-[1em] bg-cyan-500 align-middle"></span>}
    </span>
  );
};

const VoiceVisualizer = ({ isActive, isSpeaking }: { isActive: boolean, isSpeaking: boolean }) => {
  if (!isActive) return null;
  return (
    <div className="absolute inset-0 flex items-center justify-center pointer-events-none -z-10 overflow-visible">
      {[0, 1, 2].map((i) => (
        <motion.div
          key={i}
          initial={{ opacity: 0, scale: 1 }}
          animate={{ opacity: [0.8, 0], scale: [1, 2.2] }}
          transition={{ duration: isSpeaking ? 1.5 : 4, repeat: Infinity, delay: i * 0.5 }}
          className={`absolute inset-0 rounded-full border ${isSpeaking ? 'border-cyan-400' : 'border-cyan-500/30'}`}
        />
      ))}
    </div>
  );
};

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState<SectionId | null>(null);
  const [rotation, setRotation] = useState(0);
  const [lang, setLang] = useState<'en' | 'fr'>('en');
  const [portfolioData, setPortfolioData] = useState<PortfolioData>(INITIAL_DATA);
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isSoundOn, setIsSoundOn] = useState(false);
  const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
  const [isSpeakingContent, setIsSpeakingContent] = useState(false);
  const synthRef = useRef<SpeechSynthesis | null>(null);

  useEffect(() => {
    if (typeof window !== 'undefined' && window.speechSynthesis) {
      synthRef.current = window.speechSynthesis;
      const loadVoices = () => setVoices(window.speechSynthesis.getVoices());
      window.speechSynthesis.onvoiceschanged = loadVoices;
      loadVoices();
    }
  }, []);

  const getFemaleVoice = (langCode: string) => {
    const langPrefix = langCode === 'en' ? 'en' : 'fr';
    const femaleKeywords = ['google', 'microsoft', 'premium', 'natural', 'female', 'samantha', 'victoria'];
    const langVoices = voices.filter(v => v.lang.toLowerCase().startsWith(langPrefix));
    return langVoices.sort((a, b) => {
      const aScore = femaleKeywords.findIndex(k => a.name.toLowerCase().includes(k));
      const bScore = femaleKeywords.findIndex(k => b.name.toLowerCase().includes(k));
      return (aScore === -1 ? 99 : aScore) - (bScore === -1 ? 99 : bScore);
    })[0] || langVoices[0] || voices[0];
  };

  const speak = (text: string, force = false) => {
    if ((!isSoundOn && !force) || !synthRef.current) return;
    synthRef.current.cancel();
    let textToSpeak = text;
    // DYNAMIC PHONETIC REPLACEMENT FROM UI
    const nameMatch = new RegExp(portfolioData.identity.name, 'gi');
    textToSpeak = textToSpeak.replace(nameMatch, lang === 'en' ? portfolioData.identity.phoneticNameEn : portfolioData.identity.phoneticNameFr);

    const utterance = new SpeechSynthesisUtterance(textToSpeak);
    utterance.voice = getFemaleVoice(lang);
    utterance.rate = 0.95;
    utterance.onstart = () => setIsSpeakingContent(true);
    utterance.onend = () => setIsSpeakingContent(false);
    synthRef.current.speak(utterance);
  };

  const readSectionContent = () => {
    const section = getNavConfig(lang).find(n => n.id === activeSection);
    if (!section) return;
    let text = `${section.label}. `;
    if (activeSection === SectionId.PROJECTS) text += portfolioData.projects[lang].map(p => `${p.title}. ${p.description}`).join('. ');
    else if (activeSection === SectionId.EXPERIENCE) text += portfolioData.experiences[lang].map(e => `${e.role} at ${e.company}`).join('. ');
    else if (activeSection === SectionId.ABOUT) text += portfolioData.about[lang];
    speak(text, true);
  };

  useEffect(() => {
    if (activeSection && isSoundOn) {
      synthRef.current?.cancel();
      const t = setTimeout(readSectionContent, 600);
      return () => clearTimeout(t);
    }
  }, [activeSection, isSoundOn, lang]);

  useEffect(() => {
    if (isSoundOn && !activeSection) {
      const msg = lang === 'en' 
        ? `Welcome. I am ${portfolioData.identity.name}, ${portfolioData.identity.titles.en}.` 
        : `Bienvenue. Je suis ${portfolioData.identity.name}, ${portfolioData.identity.titles.fr}.`;
      speak(msg);
    }
  }, [isSoundOn, lang, activeSection]);

  useEffect(() => {
    if (activeSection !== null) return;
    const interval = setInterval(() => setRotation(r => (r + 0.15) % 360), 50);
    return () => clearInterval(interval);
  }, [activeSection]);

  const navItems = getNavConfig(lang);
  const titles = getTitles(lang);
  const currentAbout = portfolioData.about[lang];
  const currentTitle = lang === 'en' ? portfolioData.identity.titles.en : portfolioData.identity.titles.fr;

  return (
    <div className="relative min-h-screen w-full flex items-center justify-center overflow-hidden bg-slate-950 text-slate-200">
      <NeuralBackground />
      {showLoginModal && <LoginModal onLogin={() => { setShowLoginModal(false); setIsAdminOpen(true); }} onClose={() => setShowLoginModal(false)} />}
      {isAdminOpen && <AdminPanel data={portfolioData} onUpdate={(d) => { setPortfolioData(d); setIsAdminOpen(false); }} onClose={() => setIsAdminOpen(false)} />}

      <div className="fixed top-6 left-6 z-50"><button onClick={() => setShowLoginModal(true)} className="p-2 bg-slate-900 border border-slate-700 rounded-full text-slate-500 hover:text-cyan-400"><Lock size={14} /></button></div>
      <div className="fixed top-6 right-6 z-50"><button onClick={() => { synthRef.current?.cancel(); setLang(l => l === 'en' ? 'fr' : 'en'); }} className="px-4 py-2 bg-slate-900 border border-cyan-500/30 rounded-full text-cyan-400 font-mono text-xs"><Globe size={14} className="inline mr-2" />{lang.toUpperCase()}</button></div>

      <div className="fixed bottom-6 right-6 z-50">
        <button onClick={() => { setIsSoundOn(!isSoundOn); if (isSoundOn) synthRef.current?.cancel(); }} className={`p-3 rounded-full border ${isSoundOn ? 'bg-cyan-900 border-cyan-500 text-cyan-400' : 'bg-slate-900 border-slate-700 text-slate-500'}`}>
          {isSoundOn ? <Volume2 size={20} /> : <VolumeX size={20} />}
        </button>
      </div>

      <div className="relative w-full h-full flex flex-col items-center justify-center z-10 p-4">
        <AnimatePresence>
          {!activeSection && (
            <motion.div initial={{ opacity: 0, y: -50 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.9 }} className="z-20 text-center mb-12">
              <h1 className="text-3xl md:text-5xl font-bold text-white mb-4">
                <TypewriterText text={titles.welcome} />
                <span className="text-cyan-500 ml-2"><TypewriterText text={titles.portfolio} delay={1500} /></span>
              </h1>
              <div className="flex items-center justify-center gap-4 text-slate-300 font-mono text-sm">
                <span className="text-cyan-400 font-bold uppercase">{portfolioData.identity.name}</span>
                <span>|</span>
                <span>{currentTitle}</span>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <div className={`relative transition-all duration-700 ${activeSection ? 'scale-75 md:translate-x-[-30vw]' : 'scale-100'}`} style={{ width: '400px', height: '400px' }}>
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-40 h-40 z-20 group cursor-pointer" onMouseEnter={() => !isSpeakingContent && speak(lang === 'en' ? `I am ${portfolioData.identity.name}` : `Je suis ${portfolioData.identity.name}`)}>
             <VoiceVisualizer isActive={isSoundOn} isSpeaking={isSpeakingContent} />
