          </div>
          {navItems.map((item) => {
            const angleRad = ((item.angle + rotation) * Math.PI) / 180;
            const x = Math.cos(angleRad) * 140;
            const y = Math.sin(angleRad) * 140;
            return (
              <motion.button key={item.id} className={`absolute w-14 h-14 rounded-full flex items-center justify-center border transition-all ${activeSection === item.id ? 'bg-cyan-500 text-black border-cyan-400' : 'bg-slate-900 text-cyan-400 border-cyan-500/30'}`} style={{ top: `calc(50% + ${y}px)`, left: `calc(50% + ${x}px)` }} onClick={() => setActiveSection(activeSection === item.id ? null : item.id)} onMouseEnter={() => !activeSection && speak(item.label)}>
                <item.icon size={22} />
              </motion.button>
            );
          })}
        </div>

        <AnimatePresence>
          {activeSection && (
            <motion.div initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 50 }} className="absolute md:right-10 md:w-[50vw] md:h-[80vh] bg-slate-900/95 backdrop-blur-md rounded-2xl border border-cyan-500/20 shadow-2xl overflow-hidden z-40 flex flex-col">
              <div className="flex items-center justify-between p-6 border-b border-cyan-500/20">
                <h2 className="text-2xl font-bold text-white uppercase">{navItems.find(n => n.id === activeSection)?.label}</h2>
                <button onClick={() => { setActiveSection(null); synthRef.current?.cancel(); }} className="text-slate-400 hover:text-white"><X size={24} /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-6 scrollbar-thin">
                {activeSection === SectionId.ABOUT && (
                  <div className="space-y-6">
                    <div className="p-6 bg-slate-950 border border-cyan-500/30 rounded-lg text-slate-200 leading-relaxed font-mono text-sm">{currentAbout}</div>
                    <div className="grid grid-cols-2 gap-4">
                      {Object.entries(portfolioData.skills.reduce((acc, s) => ({ ...acc, [s.category]: [...(acc[s.category] || []), s] }), {} as any)).map(([cat, skills]: any) => (
                        <div key={cat} className="p-4 bg-slate-950 border border-slate-800 rounded-lg">
                          <h4 className="text-cyan-400 font-bold mb-2 text-xs uppercase">{cat}</h4>
                          <div className="flex flex-wrap gap-2">{skills.map((s: any) => <span key={s.name} className="px-2 py-1 bg-slate-900 border border-slate-700 rounded text-[10px] text-cyan-300">{s.name}</span>)}</div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                {activeSection === SectionId.CONTACT && (
                  <div className="flex flex-col items-center justify-center h-full space-y-8">
