interface AdminPanelProps {
  data: PortfolioData;
  onUpdate: (newData: PortfolioData) => void;
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ data, onUpdate, onClose }) => {
  const [activeTab, setActiveTab] = useState<'identity' | 'socials' | 'about' | 'projects'>('identity');
  const [localData, setLocalData] = useState<PortfolioData>(data);
  const [translating, setTranslating] = useState(false);

  const handleSave = () => {
    onUpdate(localData);
    alert('Database Updated Successfully.');
  };

  const updateIdentity = (field: string, value: string) => {
    setLocalData(prev => ({ ...prev, identity: { ...prev.identity, [field]: value } }));
  };

  const updateTitle = (lang: 'en' | 'fr', value: string) => {
    setLocalData(prev => ({ ...prev, identity: { ...prev.identity, titles: { ...prev.identity.titles, [lang]: value } } }));
  };

  const updateSocials = (field: string, value: string) => {
    setLocalData(prev => ({ ...prev, socials: { ...prev.socials, [field]: value } }));
  };

  const autoTranslateBio = async (source: 'en' | 'fr') => {
    setTranslating(true);
    const target = source === 'en' ? 'fr' : 'en';
    const result = await translateText(localData.about[source], target);
    setLocalData(prev => ({ ...prev, about: { ...prev.about, [target]: result } }));
    setTranslating(false);
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
      <div className="bg-slate-900 border border-cyan-500/30 w-full max-w-4xl h-[80vh] rounded-xl flex flex-col shadow-2xl overflow-hidden">
        <div className="p-4 border-b border-cyan-500/20 flex justify-between items-center bg-slate-950">
          <h2 className="text-xl font-bold text-cyan-400 flex items-center gap-2"><ShieldCheck /> CORE_CONFIG_EDITOR</h2>
          <div className="flex gap-2">
             <button onClick={handleSave} className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-500 text-white rounded font-bold transition-all"><Save size={16} /> PERSIST</button>
             <button onClick={onClose} className="p-2 text-slate-500 hover:text-white"><X size={24} /></button>
          </div>
        </div>

        <div className="flex border-b border-cyan-500/10 bg-slate-900">
           {['identity', 'socials', 'about', 'projects'].map((tab: any) => (
             <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-3 text-xs font-mono uppercase border-b-2 transition-all ${activeTab === tab ? 'border-cyan-500 text-cyan-400 bg-cyan-900/10' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
               {tab}
             </button>
           ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-900 space-y-6">
           {activeTab === 'identity' && (
             <div className="space-y-6">
                <div className="p-4 bg-slate-800 rounded-lg border border-slate-700">
                   <label className="block text-[10px] text-cyan-500 font-bold uppercase mb-2">Display Name</label>
                   <input value={localData.identity.name} onChange={(e) => updateIdentity('name', e.target.value)} className="w-full bg-slate-950 border border-slate-700 rounded p-3 text-white focus:border-cyan-500 outline-none" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div className="p-4 bg-slate-800 rounded-lg border border-slate-700">
                      <label className="block text-[10px] text-cyan-500 font-bold uppercase mb-2">Title (EN)</label>
                      <input value={localData.identity.titles.en} onChange={(e) => updateTitle('en', e.target.value)} className="w-full bg-slate-950 border border-slate-700 rounded p-3 text-white focus:border-cyan-500 outline-none" />
                   </div>
                   <div className="p-4 bg-slate-800 rounded-lg border border-slate-700">
                      <label className="block text-[10px] text-cyan-500 font-bold uppercase mb-2">Title (FR)</label>
                      <input value={localData.identity.titles.fr} onChange={(e) => updateTitle('fr', e.target.value)} className="w-full bg-slate-950 border border-slate-700 rounded p-3 text-white focus:border-cyan-500 outline-none" />
                   </div>
                </div>
                <div className="p-4 bg-slate-800 rounded-lg border border-slate-700">
                   <label className="block text-[10px] text-yellow-500 font-bold uppercase mb-2">Voice Phonetic Correction (EN)</label>
                   <input value={localData.identity.phoneticNameEn} onChange={(e) => updateIdentity('phoneticNameEn', e.target.value)} className="w-full bg-slate-950 border border-slate-700 rounded p-3 text-white focus:border-cyan-500 outline-none" placeholder="e.g. Ess-ee-ah" />
                   <p className="text-[10px] text-slate-500 mt-2">Used by the TTS engine to correctly pronounce your name.</p>
                </div>
             </div>
           )}

           {activeTab === 'socials' && (
             <div className="grid grid-cols-2 gap-4">
                {Object.keys(localData.socials).map((key) => (
                  <div key={key} className="p-4 bg-slate-800 rounded-lg border border-slate-700">
                     <label className="block text-[10px] text-cyan-500 font-bold uppercase mb-2">{key}</label>
