import { GoogleGenAI } from "@google/genai";
import { INITIAL_DATA } from "../constants";

// Initialize the Gemini API client using the API key from environment variables
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Sends a message to the Gemini API to interact with Essia's AI Digital Twin.
 * Uses gemini-3-flash-preview for basic text tasks.
 */
export const sendMessageToAI = async (message: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: {
        systemInstruction: `You are Essia Ajroud's AI Digital Twin. 
        Professional Info: ${JSON.stringify(INITIAL_DATA.identity)}
        About: ${JSON.stringify(INITIAL_DATA.about)}
        Experience: ${JSON.stringify(INITIAL_DATA.experiences)}
        Projects: ${JSON.stringify(INITIAL_DATA.projects)}
        Skills: ${JSON.stringify(INITIAL_DATA.skills)}

        Respond as Essia in a professional and friendly manner. Be concise.`,
      },
    });

    // Directly access the .text property from GenerateContentResponse
    return response.text || "I'm sorry, I couldn't generate a response.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I am currently in Offline Mode. My neural link is experiencing high latency. Please try again later.";
  }
};

/**
 * Translates text using the Gemini API.
 */
export const translateText = async (text: string, targetLang: 'en' | 'fr'): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Translate the following text to ${targetLang === 'en' ? 'English' : 'French'}. Return only the translated text, no extra commentary:\n\n${text}`,
    });

    return response.text?.trim() || text;
  } catch (error) {
    console.error("Translation Error:", error);
    return text;
  }
};

