  const getFemaleVoice = (langCode: string) => {
    const langPrefix = langCode === 'en' ? 'en' : 'fr';
    const femaleKeywords = ['google', 'microsoft', 'premium', 'natural', 'female', 'samantha', 'victoria'];
    const langVoices = voices.filter(v => v.lang.toLowerCase().startsWith(langPrefix));
    return langVoices.sort((a, b) => {
      const aScore = femaleKeywords.findIndex(k => a.name.toLowerCase().includes(k));
      const bScore = femaleKeywords.findIndex(k => b.name.toLowerCase().includes(k));
      return (aScore === -1 ? 99 : aScore) - (bScore === -1 ? 99 : bScore);
