  const [portfolioData, setPortfolioData] = useState<PortfolioData>(INITIAL_DATA);
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isSoundOn, setIsSoundOn] = useState(false);
  const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
  const [isSpeakingContent, setIsSpeakingContent] = useState(false);
  const synthRef = useRef<SpeechSynthesis | null>(null);

  useEffect(() => {
    if (typeof window !== 'undefined' && window.speechSynthesis) {
      synthRef.current = window.speechSynthesis;
      const loadVoices = () => setVoices(window.speechSynthesis.getVoices());
      window.speechSynthesis.onvoiceschanged = loadVoices;
      loadVoices();
    }
  }, []);

  const getFemaleVoice = (langCode: string) => {
    const langPrefix = langCode === 'en' ? 'en' : 'fr';
    const femaleKeywords = ['google', 'microsoft', 'premium', 'natural', 'female', 'samantha', 'victoria'];
    const langVoices = voices.filter(v => v.lang.toLowerCase().startsWith(langPrefix));
    return langVoices.sort((a, b) => {
      const aScore = femaleKeywords.findIndex(k => a.name.toLowerCase().includes(k));
      const bScore = femaleKeywords.findIndex(k => b.name.toLowerCase().includes(k));
      return (aScore === -1 ? 99 : aScore) - (bScore === -1 ? 99 : bScore);
    })[0] || langVoices[0] || voices[0];
  };

  const speak = (text: string, force = false) => {
    if ((!isSoundOn && !force) || !synthRef.current) return;
    synthRef.current.cancel();
    let textToSpeak = text;

