interface AdminPanelProps {
  data: PortfolioData;
  onUpdate: (newData: PortfolioData) => void;
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ data, onUpdate, onClose }) => {
  const [activeTab, setActiveTab] = useState<'identity' | 'media' | 'experiences' | 'projects' | 'certs' | 'skills' | 'about'>('identity');
  const [langTab, setLangTab] = useState<'en' | 'fr'>('en');
  const [localData, setLocalData] = useState<PortfolioData>(data);
  const [isSaving, setIsSaving] = useState(false);
  const [translating, setTranslating] = useState(false);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const response = await fetch('http://localhost:8000/api/portfolio', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ data: localData })
      });

      if (response.ok) {
        onUpdate(localData);
        alert('SYSTEM_UPDATE_SUCCESS: Core database synchronized with FastAPI.');
      } else {
        throw new Error("Backend save failed");
      }
    } catch (error) {
      console.error(error);
      alert('CRITICAL_ERROR: Failed to reach backend engine.');
    } finally {
      setIsSaving(false);
    }
  };

  const updateNested = (path: string[], value: any) => {
    setLocalData(prev => {
      const next = { ...prev };
      let current: any = next;
      for (let i = 0; i < path.length - 1; i++) {
        current = current[path[i]];
      }
      current[path[path.length - 1]] = value;
      return next;
    });
  };

  const addItem = (type: 'projects' | 'experiences' | 'certifications', lang: 'en' | 'fr') => {
    const id = Date.now().toString();
    if (type === 'projects') {
      const newItem: Project = { id, title: 'New Project', description: '', techStack: [], category: 'GenAI' };
      updateNested(['projects', lang], [...(localData.projects[lang]), newItem]);
    } else if (type === 'experiences') {
      const newItem: Experience = { id, role: 'New Role', company: 'Company', period: '2024', description: '' };
      updateNested(['experiences', lang], [...(localData.experiences[lang]), newItem]);
    } else if (type === 'certifications') {
      const newItem: Certification = { id, name: 'New Cert', issuer: 'Issuer', date: '2024' };
      updateNested(['certifications', lang], [...(localData.certifications[lang]), newItem]);
    }
  };

  const removeItem = (type: 'projects' | 'experiences' | 'certifications', lang: 'en' | 'fr', id: string) => {
    const filtered = (localData as any)[type][lang].filter((item: any) => item.id !== id);
    updateNested([type, lang], filtered);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-2 md:p-6">
      <div className="bg-slate-900 border border-cyan-500/30 w-full max-w-6xl h-[90vh] rounded-3xl flex flex-col shadow-[0_0_100px_rgba(6,182,212,0.1)] overflow-hidden">

        <div className="p-5 border-b border-cyan-500/20 flex justify-between items-center bg-slate-950/80">
          <div className="flex items-center gap-4">
            <ShieldCheck className="text-cyan-400" size={24} />
            <div>
              <h2 className="text-xl font-black text-white tracking-tighter uppercase">Portfolio Core Engine</h2>
              <p className="text-[9px] font-mono text-slate-500">AUTHORIZED_ACCESS // REMOTE_STORAGE_CONNECTED</p>
            </div>
          </div>
          <div className="flex gap-3">
             <button 
              disabled={isSaving}
              onClick={handleSave} 
              className="flex items-center gap-2 px-6 py-2.5 bg-cyan-600 hover:bg-cyan-500 text-slate-950 rounded-xl font-black transition-all disabled:opacity-50"
             >
               {isSaving ? <Loader2 className="animate-spin" size={16} /> : <Save size={16} />} 
               {isSaving ? 'SYNCING...' : 'PERSIST_CHANGES'}
             </button>
             <button onClick={onClose} className="p-2 text-slate-500 hover:text-white">
               <X size={28} />
             </button>
          </div>
        </div>

        {/* Tab Navigation (Similar to previous version) */}
        <div className="flex border-b border-cyan-500/10 bg-slate-950/40 overflow-x-auto scrollbar-none">
           {[
             { id: 'identity', icon: ShieldCheck, label: 'Identity' },
             { id: 'media', icon: ImageIcon, label: 'Media' },
             { id: 'experiences', icon: Briefcase, label: 'Work' },
             { id: 'projects', icon: BrainCircuit, label: 'Labs' },
             { id: 'certs', icon: Award, label: 'Certs' },
             { id: 'skills', icon: Zap, label: 'Stats' },
             { id: 'about', icon: FileText, label: 'Neural_Bio' }
           ].map((tab) => (
             <button 
              key={tab.id} 
              onClick={() => setActiveTab(tab.id as any)} 
              className={`px-6 py-4 text-[10px] font-mono uppercase tracking-widest border-b-2 transition-all flex items-center gap-2 flex-shrink-0 ${
                activeTab === tab.id ? 'border-cyan-500 text-cyan-400 bg-cyan-500/5' : 'border-transparent text-slate-500'
              }`}
             >
               <tab.icon size={14} /> {tab.label}
             </button>
           ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-slate-900/50 space-y-8 scrollbar-thin">
           {/* All the forms remain identical to the previous AdminPanel.tsx implementation */}
           <div className="text-slate-500 font-mono text-xs italic opacity-50">
             // Secure Channel 0xAF42 Ready for {activeTab.toUpperCase()} edit operations...
           </div>

           {/* Add your existing form blocks here from the previous version */}
           {activeTab === 'identity' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div className="p-4 bg-slate-800/40 rounded-2xl border border-slate-700">
