import React, { useState } from 'react';
import { 
  X, Save, Sparkles, Loader2, Image as ImageIcon, 
  ShieldCheck, FileText, Briefcase, BrainCircuit, 
  Award, Zap, Plus, Trash2 
} from 'lucide-react';
