interface AdminPanelProps {
  data: PortfolioData;
  onUpdate: (newData: PortfolioData) => void;
  onClose: () => void;
}

const API_BASE_URL = (import.meta as any).env?.VITE_API_URL || 'http://localhost:8000';

const AdminPanel: React.FC<AdminPanelProps> = ({ data, onUpdate, onClose }) => {
  const [activeTab, setActiveTab] = useState<'identity' | 'media' | 'experiences' | 'projects' | 'certs' | 'skills' | 'about'>('identity');
  const [langTab, setLangTab] = useState<'en' | 'fr'>('en');
  const [localData, setLocalData] = useState<PortfolioData>(data);
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const response = await fetch(`${API_BASE_URL}/api/portfolio`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ data: localData })
      });

      if (response.ok) {
        onUpdate(localData);
        alert('SUCCESS: Cloud database synchronized.');
      } else {
        throw new Error("Backend update failed");
      }
    } catch (error) {
      console.error(error);
      alert('ERROR: Could not persist changes to the remote server.');
    } finally {
      setIsSaving(false);
    }
  };

  const updateNested = (path: string[], value: any) => {
    setLocalData(prev => {
      const next = { ...prev };
      let current: any = next;
      for (let i = 0; i < path.length - 1; i++) {
        current = current[path[i]];
      }
      current[path[path.length - 1]] = value;
      return next;
    });
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-2 md:p-6">
      <div className="bg-slate-900 border border-cyan-500/30 w-full max-w-6xl h-[90vh] rounded-3xl flex flex-col shadow-[0_0_100px_rgba(6,182,212,0.1)] overflow-hidden">

        <div className="p-5 border-b border-cyan-500/20 flex justify-between items-center bg-slate-950/80">
          <div className="flex items-center gap-4">
            <ShieldCheck className="text-cyan-400" size={24} />
            <div>
              <h2 className="text-xl font-black text-white uppercase tracking-tighter">Admin Engine</h2>
              <p className="text-[9px] font-mono text-slate-500">REMOTE_HOST: {API_BASE_URL}</p>
            </div>
          </div>
          <div className="flex gap-3">
             <button 
              disabled={isSaving}
              onClick={handleSave} 
              className="flex items-center gap-2 px-6 py-2.5 bg-cyan-600 hover:bg-cyan-500 text-slate-950 rounded-xl font-black transition-all disabled:opacity-50"
             >
               {isSaving ? <Loader2 className="animate-spin" size={16} /> : <Save size={16} />} 
               {isSaving ? 'SYNCING...' : 'SAVE_TO_CLOUD'}
             </button>
             <button onClick={onClose} className="p-2 text-slate-500 hover:text-white">
               <X size={28} />
             </button>
          </div>
        </div>

        <div className="flex border-b border-cyan-500/10 bg-slate-950/40 overflow-x-auto">
           {[
             { id: 'identity', icon: ShieldCheck, label: 'Identity' },
             { id: 'media', icon: ImageIcon, label: 'Media' },
             { id: 'experiences', icon: Briefcase, label: 'Work' },
             { id: 'projects', icon: BrainCircuit, label: 'Labs' },
             { id: 'certs', icon: Award, label: 'Certs' },
             { id: 'skills', icon: Zap, label: 'Stats' },
             { id: 'about', icon: FileText, label: 'Bio' }
           ].map((tab) => (
             <button 
              key={tab.id} 
              onClick={() => setActiveTab(tab.id as any)} 
              className={`px-6 py-4 text-[10px] font-mono uppercase tracking-widest border-b-2 transition-all flex items-center gap-2 flex-shrink-0 ${
                activeTab === tab.id ? 'border-cyan-500 text-cyan-400 bg-cyan-500/5' : 'border-transparent text-slate-500'
              }`}
             >
               <tab.icon size={14} /> {tab.label}
             </button>
           ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-slate-900/50">
           {activeTab === 'identity' && (
              <div className="space-y-4 max-w-2xl">
                 <div className="p-4 bg-slate-800/40 rounded-2xl border border-slate-700">
                    <label className="block text-[9px] text-slate-500 font-bold uppercase mb-2">Full Name</label>
                    <input value={localData.identity.name} onChange={(e) => updateNested(['identity', 'name'], e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-white focus:border-cyan-500 outline-none font-mono text-sm" />
                 </div>
                 {/* ... other fields ... */}
              </div>
           )}
           {/* ... rest of the forms ... */}
        </div>
      </div>
    </div>
  );
};

