        <button 
          onClick={onClose}
          className="absolute top-4 right-4 text-slate-500 hover:text-white transition-colors p-1"
        >
          <X size={20} />
        </button>

        <div className="p-8 flex flex-col items-center">
          <div className="w-16 h-16 bg-cyan-950/30 rounded-full flex items-center justify-center mb-6 border border-cyan-500/30 shadow-[0_0_20px_rgba(6,182,212,0.2)]">
            <Lock size={32} className="text-cyan-400" />
          </div>

          <h2 className="text-2xl font-black text-white mb-2 tracking-tighter uppercase">Neural Shield</h2>
          <p className="text-slate-400 text-xs mb-8 text-center font-mono leading-relaxed uppercase tracking-wider">
            Restricted access. Identity verification required for kernel modification.
          </p>

          <form onSubmit={handleSubmit} className="w-full space-y-5">
            <div className="relative group">
              <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-cyan-400 transition-colors" size={18} />
              <input
                type="password"
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  setError(false);
                }}
                disabled={isSubmitting}
                placeholder="ACCESS_KEY_REQUIRED"
                className="w-full bg-slate-950 border border-slate-800 rounded-xl py-4 pl-12 pr-4 text-slate-200 focus:border-cyan-500/50 focus:ring-1 focus:ring-cyan-500/20 outline-none transition-all placeholder:text-slate-700 font-mono text-sm"
                autoFocus
              />
            </div>

            {error && (
              <motion.div 
                initial={{ opacity: 0, y: -5 }}
                animate={{ opacity: 1, y: 0 }}
                className="flex items-center justify-center gap-2 text-red-500 text-[10px] font-mono uppercase tracking-widest bg-red-500/5 p-2 rounded-lg border border-red-500/20"
              >
                <ShieldAlert size={12} />
                <span>Critical error: invalid access token</span>
              </motion.div>
