from fastapi import FastAPI, HTTPException, Body
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
import json
import os
from typing import Dict, Any

app = FastAPI(title="Essia Portfolio Backend")

# Configuration des origines autorisées
# En production, mettez l'URL de votre frontend Vercel ici.
origins = [
    "http://localhost:3000",
    "http://localhost:5173",
    "https://essia-portfolio.vercel.app", # Exemple
    "*"
]

app.add_middleware(
    CORSMiddleware,
    allow_origins=origins,
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DB_FILE = "portfolio_db.json"
# MOT DE PASSE : Utilisez une variable d'environnement ADMIN_PASSWORD. 
# Si elle n'existe pas, le système génère un mot de passe aléatoire pour la sécurité.
ADMIN_PASSWORD = os.getenv("ADMIN_PASSWORD")
if not ADMIN_PASSWORD:
    import secrets
    ADMIN_PASSWORD = secrets.token_hex(8)
    print(f"--- WARNING: No ADMIN_PASSWORD env var found. ---")
    print(f"--- GENERATED TEMPORARY PASSWORD: {ADMIN_PASSWORD} ---")

def get_default_data():
    return {
        "identity": {
            "name": "ESSIA AJROUD", 
            "titles": {"en": "AI Engineer & Data Scientist", "fr": "Ingénieure IA & Data Scientist"}, 
            "phoneticNameEn": "Ess-ee-ah", 
            "phoneticNameFr": "Ess-ya"
        },
        "projects": {"en": [], "fr": []},
        "experiences": {"en": [], "fr": []},
        "skills": [],
        "about": {"en": "I am an AI Engineer passionate about GenAI.", "fr": "Je suis une ingénieure IA passionnée par la GenAI."},
        "socials": {"email": "essia@example.com", "linkedin": "", "github": "", "phone": ""},
        "media": {"profileImage": "https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=400", "avatarImage": ""},
        "resume": {"en": "", "fr": ""},
        "certifications": {"en": [], "fr": []}
    }

def init_db():
    """Initialise la base de données locale si elle n'existe pas."""
    if not os.path.exists(DB_FILE):
        with open(DB_FILE, "w") as f:
            json.dump(get_default_data(), f, indent=4)

init_db()

class LoginRequest(BaseModel):
    password: str

class PortfolioUpdate(BaseModel):
    data: Dict[str, Any]

@app.get("/api/portfolio")
async def get_portfolio():
    try:
        if os.path.exists(DB_FILE):
            with open(DB_FILE, "r") as f:
                return json.load(f)
        return get_default_data()
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Database Read Error: {str(e)}")

@app.post("/api/login")
async def login(req: LoginRequest):
    # Comparaison sécurisée du mot de passe
    if req.password == ADMIN_PASSWORD:
        return {"status": "success", "token": "session_authorized"}
    raise HTTPException(status_code=401, detail="Invalid kernel access key")

@app.put("/api/portfolio")
async def update_portfolio(update: PortfolioUpdate):
    try:
        # En production, sur Render (gratuit), ce fichier sera effacé au redémarrage.
        # Pour une solution pérenne gratuite, utilisez Supabase ou MongoDB Atlas.
        with open(DB_FILE, "w") as f:
            json.dump(update.data, f, indent=4)
        return {"status": "Database Synchronized"}
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Database Write Error: {str(e)}")

if __name__ == "__main__":
    import uvicorn
    # Le port est défini par Render ou par défaut à 8000
    port = int(os.getenv("PORT", 8000))
    uvicorn.run(app, host="0.0.0.0", port=port)

import React, { useState } from 'react';
// Added motion import to fix "Cannot find name 'motion'" error on line 82 and 89
import { motion } from 'framer-motion';
import { X, Lock, KeyRound, ArrowRight, ShieldAlert } from 'lucide-react';

interface LoginModalProps {
  onLogin: () => void;
  onClose: () => void;
}

const LoginModal: React.FC<LoginModalProps> = ({ onLogin, onClose }) => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError(false);

    try {
      // En production, on appelle l'API backend pour vérifier le mot de passe
      const API_BASE_URL = (import.meta as any).env?.VITE_API_URL || 'http://localhost:8000';
      const response = await fetch(`${API_BASE_URL}/api/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password })
      });

      if (response.ok) {
        onLogin();
      } else {
        throw new Error("Unauthorized");
      }
    } catch (err) {
      setError(true);
      setPassword('');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/95 backdrop-blur-md p-4">
      <div className="bg-slate-900 border border-cyan-500/20 w-full max-w-md rounded-2xl shadow-2xl overflow-hidden relative">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-cyan-500 to-transparent opacity-50"></div>

        <button 
          onClick={onClose}
          className="absolute top-4 right-4 text-slate-500 hover:text-white transition-colors p-1"
        >
          <X size={20} />
        </button>

        <div className="p-8 flex flex-col items-center">
          <div className="w-16 h-16 bg-cyan-950/30 rounded-full flex items-center justify-center mb-6 border border-cyan-500/30 shadow-[0_0_20px_rgba(6,182,212,0.2)]">
            <Lock size={32} className="text-cyan-400" />
          </div>

          <h2 className="text-2xl font-black text-white mb-2 tracking-tighter uppercase">Neural Shield</h2>
          <p className="text-slate-400 text-xs mb-8 text-center font-mono leading-relaxed uppercase tracking-wider">
            Restricted access. Identity verification required for kernel modification.
          </p>

          <form onSubmit={handleSubmit} className="w-full space-y-5">
            <div className="relative group">
              <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-cyan-400 transition-colors" size={18} />
              <input
                type="password"
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  setError(false);
                }}
                disabled={isSubmitting}
                placeholder="ACCESS_KEY_REQUIRED"
                className="w-full bg-slate-950 border border-slate-800 rounded-xl py-4 pl-12 pr-4 text-slate-200 focus:border-cyan-500/50 focus:ring-1 focus:ring-cyan-500/20 outline-none transition-all placeholder:text-slate-700 font-mono text-sm"
                autoFocus
              />
            </div>

            {error && (
              /* Fix: Use motion.div from framer-motion which is now imported */
              <motion.div 
                initial={{ opacity: 0, y: -5 }}
                animate={{ opacity: 1, y: 0 }}
                className="flex items-center justify-center gap-2 text-red-500 text-[10px] font-mono uppercase tracking-widest bg-red-500/5 p-2 rounded-lg border border-red-500/20"
              >
                <ShieldAlert size={12} />
                <span>Critical error: invalid access token</span>
              </motion.div>
            )}

            <button
              type="submit"
              disabled={isSubmitting || !password}
              className="w-full bg-cyan-600 hover:bg-cyan-500 disabled:bg-slate-800 text-slate-950 font-black py-4 rounded-xl shadow-lg shadow-cyan-500/10 transition-all flex items-center justify-center gap-3 group overflow-hidden relative"
            >
              {isSubmitting ? (
                <div className="flex items-center gap-2">
                  <div className="w-4 h-4 border-2 border-slate-950/30 border-t-slate-950 rounded-full animate-spin"></div>
                  <span>VERIFYING...</span>
                </div>
              ) : (
                <>
                  <span>AUTHORIZE_ACCESS</span>
                  <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
                </>
              )}
            </button>
          </form>

          <div className="mt-10 pt-6 border-t border-slate-800 w-full text-center">
             <p className="text-[9px] text-slate-600 font-mono tracking-[0.2em] uppercase">
                System Status: encrypted_link_stable
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginModal;
